const collections = ['claude_memories','short_term_memory','working_memory','learnings','procedures','trajectories','episodes'];
const apiKey = $env.QDRANT_API_KEY;
let allPoints = [];
for (const col of collections) {
  try {
    const resp = await fetch(`http://localhost:6334/collections/${col}/points/scroll`, {
      method: 'POST',
      headers: { 'api-key': apiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ limit: 1000, with_payload: true, with_vector: false, filter: { must_not: [{ is_empty: { key: 'expires_at' } }] } })
    });
    if (resp.ok) {
      const data = await resp.json();
      const pts = (data.result?.points || []).map(p => ({ ...p, _collection: col }));
      allPoints = allPoints.concat(pts);
    }
  } catch {}
}
return [{ json: { result: { points: allPoints } } }];

const collections = ['claude_memories','short_term_memory','working_memory','learnings','procedures','trajectories','episodes'];
const apiKey = $env.QDRANT_API_KEY;
const sixtyDaysAgo = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000);
let stalePoints = [];
for (const col of collections) {
  try {
    const resp = await fetch(`http://localhost:6334/collections/${col}/points/scroll`, {
      method: 'POST',
      headers: { 'api-key': apiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ limit: 1000, with_payload: true, with_vector: false })
    });
    if (resp.ok) {
      const data = await resp.json();
      const pts = (data.result?.points || []).filter(p => {
        const created = p.payload?.created_at;
        return (!p.payload?.access_count || p.payload.access_count === 0) && created && new Date(created) < sixtyDaysAgo;
      }).map(p => ({ ...p, _collection: col }));
      stalePoints = stalePoints.concat(pts);
    }
  } catch {}
}
return [{ json: { result: { points: stalePoints } } }];

const items = $input.all();
const now = new Date();
const monthName = now.toLocaleString('en-US', { month: 'long', year: 'numeric' });
const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
const sixtyDaysAgo = new Date(now.getTime() - 60 * 24 * 60 * 60 * 1000);
const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

// Parse data from the 4 HTTP requests
const expiringData = items[0]?.json?.result?.points || [];
const allMemories = items[1]?.json?.result?.points || [];
const auditStores = items[2]?.json?.result?.points || [];
const auditRedactions = items[3]?.json?.result?.points || [];

// Expiring within 30 days
const expiringSoon = expiringData.filter(p => {
  const exp = p.payload?.expires_at;
  return exp && new Date(exp) <= thirtyDaysFromNow && new Date(exp) > now;
});

// Never accessed + older than 60 days
const neverAccessed = allMemories.filter(p => {
  const created = p.payload?.created_at;
  return (!p.payload?.access_count || p.payload.access_count === 0) &&
    created && new Date(created) < sixtyDaysAgo;
});

// Sensitive stores this month
const sensitiveStores = auditStores.filter(p => {
  const ts = p.payload?.timestamp;
  const sens = p.payload?.sensitivity || p.payload?.details?.sensitivity;
  return ts && new Date(ts) > monthAgo &&
    (sens === 'sensitive' || sens === 'restricted');
});

// Redactions this month
const recentRedactions = auditRedactions.filter(p => {
  const ts = p.payload?.timestamp;
  return ts && new Date(ts) > monthAgo;
});

// Count by sensitivity
const bySensitivity = {};
allMemories.forEach(p => {
  const s = p.payload?.sensitivity || 'unclassified';
  bySensitivity[s] = (bySensitivity[s] || 0) + 1;
});

// Build markdown
let md = `# Memory Review — ${monthName}\n\n`;

md += `## Expiring Soon (act within 30 days)\n\n`;
if (expiringSoon.length === 0) {
  md += `No sensitive memories expiring in the next 30 days.\n\n`;
} else {
  md += `| ID | Preview | Sensitivity | Created | Expires |\n`;
  md += `|----|---------|-------------|---------|---------|\n`;
  expiringSoon.forEach(p => {
    const preview = (p.payload?.content || '').slice(0, 50).replace(/\|/g, '/');
    md += `| ${String(p.id).slice(0, 8)}... | "${preview}" | ${p.payload?.sensitivity || '?'} | ${(p.payload?.created_at || '?').slice(0, 10)} | ${(p.payload?.expires_at || '?').slice(0, 10)} |\n`;
  });
  md += `\nActions: Promote to internal (keep forever) or let expire.\n\n`;
}

md += `## Never Accessed (candidates for deletion)\n\n`;
if (neverAccessed.length === 0) {
  md += `No stale memories found.\n\n`;
} else {
  md += `| ID | Preview | Type | Created | Project |\n`;
  md += `|----|---------|------|---------|---------|\n`;
  neverAccessed.slice(0, 20).forEach(p => {
    const preview = (p.payload?.content || '').slice(0, 50).replace(/\|/g, '/');
    md += `| ${String(p.id).slice(0, 8)}... | "${preview}" | ${p.payload?.type || '?'} | ${(p.payload?.created_at || '?').slice(0, 10)} | ${p.payload?.project || '?'} |\n`;
  });
  if (neverAccessed.length > 20) md += `\n...and ${neverAccessed.length - 20} more\n`;
  md += `\n`;
}

md += `## Sensitive Activity This Month\n\n`;
md += `- ${sensitiveStores.length} sensitive/restricted memories stored\n`;
md += `- ${recentRedactions.length} redactions performed\n\n`;

md += `## Stats\n\n`;
md += `- Total memories scanned: ${allMemories.length}\n`;
md += `- By sensitivity: ${Object.entries(bySensitivity).map(([k, v]) => `${k} (${v})`).join(', ')}\n`;
md += `- Audit log entries scanned: ${auditStores.length + auditRedactions.length}\n`;

return [{ json: { markdown: md, filename: `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')} Memory Review.md`, stats: { expiring_soon: expiringSoon.length, never_accessed: neverAccessed.length, sensitive_stores: sensitiveStores.length, redactions: recentRedactions.length, total: allMemories.length, by_sensitivity: bySensitivity } } }];
